type Agendado = { quando: number; fn: () => void };
let agora = 0;
const fila: Agendado[] = [];

const agendar = (fn: () => void, ms: number) => {
  fila.push({ quando: agora + ms, fn });
};

function avancar(ms: number) {
  const fim = agora + ms;
  fila.sort((a, b) => a.quando - b.quando);
  while (fila[0] && fila[0].quando <= fim) {
    const t = fila.shift()!;
    agora = t.quando;
    t.fn();
  }
  agora = fim;
}

agendar(() => console.log('timeout em', agora), 30000);
agendar(() => console.log('lembrete em', agora), 5000);
avancar(4999);
console.log('nada ainda em', agora);
avancar(1);
avancar(60000);
console.log('fim em', agora);

