let checagens = 0;
const botaoVisivel = () => ++checagens >= 3;

async function esperaAte(cond: () => boolean, tentativas = 5): Promise<number> {
  for (let i = 1; i <= tentativas; i++) {
    if (cond()) return i;
    await new Promise((r) => setTimeout(r, 20));
  }
  throw new Error('tempo esgotado');
}

console.log('olhando uma vez:', botaoVisivel());

checagens = 0;
console.log('tentando de novo: achou na tentativa', await esperaAte(botaoVisivel));

import assert from 'node:assert/strict';

type Regra = (usados: number, capacidade: number) => boolean;
const original: Regra = (u, c) => u <= c;
const mutante: Regra = (u, c) => u < c;

const suiteFraca = (cabe: Regra) => {
  assert.equal(cabe(100, 480), true);
  assert.equal(cabe(900, 480), false);
};
const suiteForte = (cabe: Regra) => {
  suiteFraca(cabe);
  assert.equal(cabe(480, 480), true);
};

function roda(nome: string, suite: (r: Regra) => void, regra: Regra) {
  try { suite(regra); console.log(nome, 'passou'); }
  catch { console.log(nome, 'REPROVOU'); }
}

roda('fraca x original:', suiteFraca, original);
roda('fraca x mutante:', suiteFraca, mutante);
roda('forte x original:', suiteForte, original);
roda('forte x mutante:', suiteForte, mutante);

